package rules

import "testing"

// The expected output of every case and configuration comes from the PHP engine.
func TestNoAliasFunctionsConfigs(t *testing.T) {
	t.Parallel()
	fixers := []fixerRule{
		NoAliasFunctions{},
		NoAliasFunctions{}.WithConfig(map[string]any{"sets": []any{"@internal", "@IMAP", "@pg"}}).(fixerRule),
		NoAliasFunctions{}.WithConfig(map[string]any{"sets": []any{"@all"}}).(fixerRule),
		NoAliasFunctions{}.WithConfig(map[string]any{"sets": []any{}}).(fixerRule),
		NoAliasFunctions{}.WithConfig(map[string]any{"sets": []any{"@ldap", "@mysqli", "@oci", "@odbc"}}).(fixerRule),
		NoAliasFunctions{}.WithConfig(map[string]any{"sets": []any{"@mbreg", "@openssl", "@sodium"}}).(fixerRule),
		NoAliasFunctions{}.WithConfig(map[string]any{"sets": map[string]any{"0": "@exif", "1": "@ftp", "3": "@posix", "4": "@pcntl"}}).(fixerRule),
		NoAliasFunctions{}.WithConfig(map[string]any{"sets": []any{"@time"}}).(fixerRule),
		NoAliasFunctions{}.WithConfig(map[string]any{"sets": []any{"@internal", "@all", "@time"}}).(fixerRule),
	}
	cases := []struct {
		src  string
		want [9]string
	}{
		{"<?php\n$a = sizeof($b);\n$a = imap_header($s, 1);\n$a = pg_exec($c);\nldap_close($l);\nmysqli_execute($s);\noci_free_cursor($c);\nodbc_do($c, $q);\nmbereg_search_getregs();\nmbsplit($p, $s);\nopenssl_get_publickey($k);\nsodium_crypto_scalarmult_base($k);\nread_exif_data($f);\nftp_quit($f);\nposix_errno();\npcntl_errno();\n$t = mktime();\n$t = gmmktime();\n", [9]string{"<?php\n$a = count($b);\n$a = imap_headerinfo($s, 1);\n$a = pg_query($c);\nldap_close($l);\nmysqli_execute($s);\noci_free_cursor($c);\nodbc_do($c, $q);\nmbereg_search_getregs();\nmbsplit($p, $s);\nopenssl_get_publickey($k);\nsodium_crypto_scalarmult_base($k);\nread_exif_data($f);\nftp_quit($f);\nposix_errno();\npcntl_errno();\n$t = mktime();\n$t = gmmktime();\n", "<?php\n$a = count($b);\n$a = imap_headerinfo($s, 1);\n$a = pg_query($c);\nldap_close($l);\nmysqli_execute($s);\noci_free_cursor($c);\nodbc_do($c, $q);\nmbereg_search_getregs();\nmbsplit($p, $s);\nopenssl_get_publickey($k);\nsodium_crypto_scalarmult_base($k);\nread_exif_data($f);\nftp_quit($f);\nposix_errno();\npcntl_errno();\n$t = mktime();\n$t = gmmktime();\n", "<?php\n$a = count($b);\n$a = imap_headerinfo($s, 1);\n$a = pg_query($c);\nldap_unbind($l);\nmysqli_stmt_execute($s);\noci_free_statement($c);\nodbc_exec($c, $q);\nmb_ereg_search_getregs();\nmb_split($p, $s);\nopenssl_pkey_get_public($k);\nsodium_crypto_box_publickey_from_secretkey($k);\nexif_read_data($f);\nftp_close($f);\nposix_get_last_error();\npcntl_get_last_error();\n$t = time();\n$t = time();\n", "<?php\n$a = sizeof($b);\n$a = imap_header($s, 1);\n$a = pg_exec($c);\nldap_close($l);\nmysqli_execute($s);\noci_free_cursor($c);\nodbc_do($c, $q);\nmbereg_search_getregs();\nmbsplit($p, $s);\nopenssl_get_publickey($k);\nsodium_crypto_scalarmult_base($k);\nread_exif_data($f);\nftp_quit($f);\nposix_errno();\npcntl_errno();\n$t = mktime();\n$t = gmmktime();\n", "<?php\n$a = sizeof($b);\n$a = imap_header($s, 1);\n$a = pg_exec($c);\nldap_unbind($l);\nmysqli_stmt_execute($s);\noci_free_statement($c);\nodbc_exec($c, $q);\nmbereg_search_getregs();\nmbsplit($p, $s);\nopenssl_get_publickey($k);\nsodium_crypto_scalarmult_base($k);\nread_exif_data($f);\nftp_quit($f);\nposix_errno();\npcntl_errno();\n$t = mktime();\n$t = gmmktime();\n", "<?php\n$a = sizeof($b);\n$a = imap_header($s, 1);\n$a = pg_exec($c);\nldap_close($l);\nmysqli_execute($s);\noci_free_cursor($c);\nodbc_do($c, $q);\nmb_ereg_search_getregs();\nmb_split($p, $s);\nopenssl_pkey_get_public($k);\nsodium_crypto_box_publickey_from_secretkey($k);\nread_exif_data($f);\nftp_quit($f);\nposix_errno();\npcntl_errno();\n$t = mktime();\n$t = gmmktime();\n", "<?php\n$a = sizeof($b);\n$a = imap_header($s, 1);\n$a = pg_exec($c);\nldap_close($l);\nmysqli_execute($s);\noci_free_cursor($c);\nodbc_do($c, $q);\nmbereg_search_getregs();\nmbsplit($p, $s);\nopenssl_get_publickey($k);\nsodium_crypto_scalarmult_base($k);\nexif_read_data($f);\nftp_close($f);\nposix_get_last_error();\npcntl_get_last_error();\n$t = mktime();\n$t = gmmktime();\n", "<?php\n$a = sizeof($b);\n$a = imap_header($s, 1);\n$a = pg_exec($c);\nldap_close($l);\nmysqli_execute($s);\noci_free_cursor($c);\nodbc_do($c, $q);\nmbereg_search_getregs();\nmbsplit($p, $s);\nopenssl_get_publickey($k);\nsodium_crypto_scalarmult_base($k);\nread_exif_data($f);\nftp_quit($f);\nposix_errno();\npcntl_errno();\n$t = time();\n$t = time();\n", "<?php\n$a = count($b);\n$a = imap_headerinfo($s, 1);\n$a = pg_query($c);\nldap_unbind($l);\nmysqli_stmt_execute($s);\noci_free_statement($c);\nodbc_exec($c, $q);\nmb_ereg_search_getregs();\nmb_split($p, $s);\nopenssl_pkey_get_public($k);\nsodium_crypto_box_publickey_from_secretkey($k);\nexif_read_data($f);\nftp_close($f);\nposix_get_last_error();\npcntl_get_last_error();\n$t = time();\n$t = time();\n"}},
		{"<?php\n$t = mktime(1, 2, 3);\n$t = mktime( );\n$t = mktime(/* none */);\n$t = MKTIME();\n$t = \\gmmktime();\n$t = mktime(...);\n", [9]string{"<?php\n$t = mktime(1, 2, 3);\n$t = mktime( );\n$t = mktime(/* none */);\n$t = MKTIME();\n$t = \\gmmktime();\n$t = mktime(...);\n", "<?php\n$t = mktime(1, 2, 3);\n$t = mktime( );\n$t = mktime(/* none */);\n$t = MKTIME();\n$t = \\gmmktime();\n$t = mktime(...);\n", "<?php\n$t = mktime(1, 2, 3);\n$t = time( );\n$t = time(/* none */);\n$t = time();\n$t = \\time();\n$t = mktime(...);\n", "<?php\n$t = mktime(1, 2, 3);\n$t = mktime( );\n$t = mktime(/* none */);\n$t = MKTIME();\n$t = \\gmmktime();\n$t = mktime(...);\n", "<?php\n$t = mktime(1, 2, 3);\n$t = mktime( );\n$t = mktime(/* none */);\n$t = MKTIME();\n$t = \\gmmktime();\n$t = mktime(...);\n", "<?php\n$t = mktime(1, 2, 3);\n$t = mktime( );\n$t = mktime(/* none */);\n$t = MKTIME();\n$t = \\gmmktime();\n$t = mktime(...);\n", "<?php\n$t = mktime(1, 2, 3);\n$t = mktime( );\n$t = mktime(/* none */);\n$t = MKTIME();\n$t = \\gmmktime();\n$t = mktime(...);\n", "<?php\n$t = mktime(1, 2, 3);\n$t = time( );\n$t = time(/* none */);\n$t = time();\n$t = \\time();\n$t = mktime(...);\n", "<?php\n$t = mktime(1, 2, 3);\n$t = time( );\n$t = time(/* none */);\n$t = time();\n$t = \\time();\n$t = mktime(...);\n"}},
		{"<?php\n$a = SizeOf($b);\n$a = $o->sizeof($b);\n$a = Foo::mktime();\n$a = \\Foo\\mktime();\nfunction mktime() {}\n$a = new join();\n$a = sizeof;\n", [9]string{"<?php\n$a = count($b);\n$a = $o->sizeof($b);\n$a = Foo::mktime();\n$a = \\Foo\\mktime();\nfunction mktime() {}\n$a = new join();\n$a = sizeof;\n", "<?php\n$a = count($b);\n$a = $o->sizeof($b);\n$a = Foo::mktime();\n$a = \\Foo\\mktime();\nfunction mktime() {}\n$a = new join();\n$a = sizeof;\n", "<?php\n$a = count($b);\n$a = $o->sizeof($b);\n$a = Foo::mktime();\n$a = \\Foo\\mktime();\nfunction mktime() {}\n$a = new join();\n$a = sizeof;\n", "<?php\n$a = SizeOf($b);\n$a = $o->sizeof($b);\n$a = Foo::mktime();\n$a = \\Foo\\mktime();\nfunction mktime() {}\n$a = new join();\n$a = sizeof;\n", "<?php\n$a = SizeOf($b);\n$a = $o->sizeof($b);\n$a = Foo::mktime();\n$a = \\Foo\\mktime();\nfunction mktime() {}\n$a = new join();\n$a = sizeof;\n", "<?php\n$a = SizeOf($b);\n$a = $o->sizeof($b);\n$a = Foo::mktime();\n$a = \\Foo\\mktime();\nfunction mktime() {}\n$a = new join();\n$a = sizeof;\n", "<?php\n$a = SizeOf($b);\n$a = $o->sizeof($b);\n$a = Foo::mktime();\n$a = \\Foo\\mktime();\nfunction mktime() {}\n$a = new join();\n$a = sizeof;\n", "<?php\n$a = SizeOf($b);\n$a = $o->sizeof($b);\n$a = Foo::mktime();\n$a = \\Foo\\mktime();\nfunction mktime() {}\n$a = new join();\n$a = sizeof;\n", "<?php\n$a = count($b);\n$a = $o->sizeof($b);\n$a = Foo::mktime();\n$a = \\Foo\\mktime();\nfunction mktime() {}\n$a = new join();\n$a = sizeof;\n"}},
	}
	for _, c := range cases {
		for k, f := range fixers {
			got, changed := apply(t, f, c.src)
			if got != c.want[k] || changed != (c.want[k] != c.src) {
				t.Errorf("config %d src=%q\nchanged=%v got=%q\nwant=%q", k, c.src, changed, got, c.want[k])
			}
		}
	}
}
